        ready = [k for k,parents in data['deps'].items() if k not in finished and all(p in finished for p in parents)]
        if not ready:
            return None
        for node in ready:
            preds = data['deps'][node]
            if preds:
                start = max(finished[p] for p in preds)
            else:
                start = 0
            finished[node] = start + data['durations'][node]
    return finished

